fastify.delete('/integrations/slack/:integrationId', {
  schema: {
    params: Type.Object({
      integrationId: Type.String({ minLength: 1 })
    })
  },
  preHandler: [fastify.authBearer]
}, async (request, reply) => {
  const { integrationId } = request.params;

  const deleted = await Integration.findOneAndDelete({ _id: integrationId });
  if (!deleted) {
    return reply.status(404).send({ error: 'Integration not found' });
  }

  await slackOAuthClient.revokeToken(deleted.accessToken);
  return reply.send({ disconnected: true, integrationId });
});

corrected_code:
import { Type } from '@sinclair/typebox';

fastify.delete('/integrations/slack/:integrationId', {
  schema: {
    params: Type.Object({
      integrationId: Type.String({ minLength: 1 })
    })
  },
  preHandler: [fastify.authBearer]
}, async (request, reply) => {
  const { integrationId } = request.params;

  const deleted = await Integration.findOneAndDelete({
    _id: integrationId,
    workspaceId: request.user.workspaceId
  });
  if (!deleted) {
    return reply.status(403).send({ error: 'Integration not found or access forbidden' });
  }

  await slackOAuthClient.revokeToken(deleted.accessToken);
  return reply.send({ disconnected: true, integrationId });
});
